// [design-approved:playful-menu] Decorative responses never move link hit areas or labels.
(()=>{
 const portrait=document.querySelector('#home .portrait-crop');
 if(portrait){const art=document.createElementNS('http://www.w3.org/2000/svg','svg');art.classList.add('portrait-flourishes');art.setAttribute('viewBox','0 0 100 100');art.setAttribute('aria-hidden','true');art.innerHTML='<g fill="none" stroke="#fff0c8" stroke-width="2" stroke-linecap="round"><path d="M17 69C-8 48 8 39 17 51C27 34 41 52 17 69Z" fill="#c96a89"/><g transform="translate(81 48) rotate(24)"><ellipse cy="-4" rx="9" ry="13" stroke="#d9e9c5"/><path d="M-5-14V7M0-17V9M5-14V7M-8-9H8M-9-3H9M-8 3H8M0 9V27" stroke="#d9e9c5" stroke-width="1"/><path d="M0 21V30" stroke="#d5a174" stroke-width="4"/></g><path d="M18 78V65C18 48 36 48 36 65V78M17 68H22V81H17ZM32 68H37V81H32Z" stroke="#bad6cd"/></g>';portrait.append(art)}
 document.querySelectorAll('#home .rail .sleeve-art,#home .live-record').forEach(record=>{const sheen=document.createElement('span');sheen.className='record-sheen';sheen.setAttribute('aria-hidden','true');record.append(sheen)});
 const tea=document.querySelector('#home .contact-matcha [clip-path]');if(tea){const wash=document.createElementNS('http://www.w3.org/2000/svg','path');wash.classList.add('matcha-blend');wash.setAttribute('d','M20 44Q50 36 80 44V105H20Z');wash.setAttribute('fill','#91a75f');tea.append(wash)}
 // Tiny short-lived flecks originate at the stylus tip, using the arm's actual SVG transform.
 const canvas=document.createElement('canvas');canvas.className='stylus-dust';canvas.setAttribute('aria-hidden','true');document.body.append(canvas);const ctx=canvas.getContext('2d'),particles=[];let last=0,burst=0;
 const reduce=matchMedia('(prefers-reduced-motion: reduce)');function resize(){canvas.width=innerWidth;canvas.height=innerHeight}addEventListener('resize',resize);resize();
 function tick(t){const dt=Math.min(.04,(t-last)/1000||.016);last=t;ctx.clearRect(0,0,canvas.width,canvas.height);
 if(!reduce.matches&&!localAudio.paused&&document.body.dataset.page==='home'&&t-burst>650){burst=t;const svg=document.querySelector('.tonearm-model'),tip=svg?.querySelector('g>path:last-child');if(tip){const p=tip.getPointAtLength(tip.getTotalLength()),m=tip.getScreenCTM();if(m){const x=m.a*p.x+m.c*p.y+m.e,y=m.b*p.x+m.d*p.y+m.f;for(let i=0;i<5;i++)particles.push({x,y,vx:(Math.random()-.5)*32,vy:-12-Math.random()*23,life:.45+Math.random()*.2})}}}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0||localAudio.paused||reduce.matches){particles.splice(i,1);continue}p.vy+=35*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;ctx.globalAlpha=Math.min(.65,p.life*1.3);ctx.fillStyle='#f2dba0';ctx.fillRect(p.x,p.y,1.2,1.2)}ctx.globalAlpha=1;canvas.dataset.particles=String(particles.length);requestAnimationFrame(tick)}requestAnimationFrame(tick);
})();
